function Get-MarkerAgentPluginField {
    param(
        [Parameter(Mandatory)][string]$MarkerFile,
        [Parameter(Mandatory)][string]$FieldName
    )

    $inAgentPlugins = $false
    foreach ($line in (Get-Content $MarkerFile)) {
        if ($line -match '^agent_plugins:') {
            $inAgentPlugins = $true
            continue
        }
        if ($inAgentPlugins -and $line -match '^\S') {
            break
        }
        if ($inAgentPlugins -and $line -match "^\s+${FieldName}:\s*(.+)$") {
            return $Matches[1].Trim()
        }
    }
    return $null
}

function Test-MarkerSignature {
    param(
        [Parameter(Mandatory)][string]$MarkerFile
    )

    $apiKey = [REDACTED] -MarkerFile $MarkerFile -FieldName 'apiKey'
    $port = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'port'
    $baseUrl = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'baseUrl'
    $workspace = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'workspace'
    $workspacePath = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'workspacePath'
    $markerPid = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'pid'
    $startedAt = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'startedAt'
    $markerWrittenAtUtc = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'markerWrittenAtUtc'
    $serverStartedAtUtc = Get-MarkerField -MarkerFile $MarkerFile -FieldName 'serverStartedAtUtc'

    # Build canonical payload (marker-v1 format)
    $payload = "canonicalization=marker-v1`n"
    $payload += "port=$port`n"
    $payload += "baseUrl=$baseUrl`n"
    $payload += "apiKey=[REDACTED]`n"
    $payload += "workspace=$workspace`n"
    $payload += "workspacePath=$workspacePath`n"
    $payload += "pid=$markerPid`n"
    $payload += "startedAt=$startedAt`n"
    $payload += "markerWrittenAtUtc=$markerWrittenAtUtc`n"
    $payload += "serverStartedAtUtc=$serverStartedAtUtc`n"

    # Extract endpoints
    $inEndpoints = $false
    foreach ($line in (Get-Content $MarkerFile)) {
        if ($line -match '^endpoints:') {
            $inEndpoints = $true
            continue
        }
        if ($inEndpoints -and $line -match '^\S') {
            break
        }
        if ($inEndpoints -and $line -match '^\s+(\S+):\s*(.+)$') {
            $key = $Matches[1].Trim()
            $val = $Matches[2].Trim()
            $payload += "endpoints.$key=$val`n"
        }
    }

    $agentPluginsPolicy = Get-MarkerAgentPluginField -MarkerFile $MarkerFile -FieldName 'policy'
    $agentPluginsDigest = Get-MarkerAgentPluginField -MarkerFile $MarkerFile -FieldName 'contract_digest'
    if ($agentPluginsPolicy -or $agentPluginsDigest) {
        $payload += "agentPlugins.policy=$agentPluginsPolicy`n"
        $payload += "agentPlugins.contractDigest=$agentPluginsDigest`n"
    }

    # Extract stored signature
    $storedSignature = $null
    $inSignature = $false
    foreach ($line in (Get-Content $MarkerFile)) {
        if ($line -match '^signature:') {
            $inSignature = $true
            continue
        }
        if ($inSignature -and $line -match '^\S') {
            break
        }
        if ($inSignature -and $line -match '^\s+value:\s*(.+)$') {
            $storedSignature = $Matches[1].Trim()
        }
    }

    if (-not $storedSignature) {
        Write-Error "No signature value found in marker file"
        return $false
    }

    # Compute HMAC-SHA256
    $keyBytes = [System.Text.Encoding]::UTF8.GetBytes($apiKey)
    $payloadBytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
    $hmac = New-Object System.Security.Cryptography.HMACSHA256
    $hmac.Key = $keyBytes
    $hashBytes = $hmac.ComputeHash($payloadBytes)
    $computed = ($hashBytes | ForEach-Object { $_.ToString('X2') }) -join ''

    return ($computed -eq $storedSignature)
}

function Invoke-FullBootstrap {
    param(
        [string]$StartDir = (Get-Location).Path
    )

    # Find marker
    try {
        $markerFile = Find-MarkerFile -StartDir $StartDir
    } catch {
        Write-Error "MCP_UNTRUSTED: No marker file found"
        return $false
    }

    # Verify signature
    if (-not (Test-MarkerSignature -MarkerFile $markerFile)) {
        Write-Error "MCP_UNTRUSTED: Signature verification failed"
        return $false
    }

    # Health nonce check
    $baseUrl = Get-MarkerField -MarkerFile $markerFile -FieldName 'baseUrl'
    $nonce = "nonce-$(Get-Date -Format 'yyyyMMddHHmmss')-$PID"
    try {
        $response = Invoke-RestMethod -Uri "$baseUrl/health?nonce=$nonce" -TimeoutSec 5
        if ($response.nonce -ne $nonce) {
            Write-Error "MCP_UNTRUSTED: Nonce verification failed"
            return $false
        }
    } catch {
        Write-Error "MCP_UNTRUSTED: Health check failed - $_"
        return $false
    }

    return $true
}
function Invoke-ReplMethod {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Method,
        [string]$ParamsYaml = ''
    )

    # Local plugin-shim verbs: record the boolean outcome on the script-scoped
    # success flag (so the script-entry exit code is truthful) and return without
    # emitting the boolean to stdout. Emitting it leaked "True" lines, and leaving
    # the flag unset made the script-entry exit 1 even on a successful persist.
    switch -Wildcard ($Method) {
        'workflow.sessionlog.beginTurn'       { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowBeginTurn -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.openSession'     { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowOpenSession -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.updateTurn'      { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowUpdateTurn -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.appendActions'   { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowAppendActions -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.appendDialog'    { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowAppendDialog -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.completeTurn'    { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowCompleteTurn -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.failTurn'        { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowFailTurn -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.setTurnTitle'    { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowSetTurnTitle -ParamsYaml $ParamsYaml); return }
        'workflow.sessionlog.setSessionTitle' { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowSetSessionTitle -ParamsYaml $ParamsYaml); return }
        'workflow.failsafe.drain' {
            # These two verbs report a YAML document to stdout as well as a boolean
            # outcome, so they return a result object instead of a bare boolean.
            $drainResult = Invoke-WorkflowFailsafeDrain -ParamsYaml $ParamsYaml
            $script:LastInvokeReplMethodSuccess = [bool]$drainResult.Success
            $drainResult.Output
            return
        }
        'workflow.failsafe.status' {
            $failsafeStatusResult = Invoke-WorkflowFailsafeStatus -ParamsYaml $ParamsYaml
            $script:LastInvokeReplMethodSuccess = [bool]$failsafeStatusResult.Success
            $failsafeStatusResult.Output
            return
        }
    }

    $r = Invoke-ReplRaw -Method $Method -ParamsYaml $ParamsYaml
    if ($r.Output) {
        $script:LastInvokeReplMethodSuccess = [bool]$r.Success
        $r.Output
        return
    }

    $script:LastInvokeReplMethodSuccess = [bool]$r.Success
    return [bool]$r.Success
}

# Script-entry: only when invoked directly with -Method (not when dot-sourced).
if ($Method -and $MyInvocation.InvocationName -ne '.') {
    $script:LastInvokeReplMethodSuccess = $false
    Invoke-ReplMethod -Method $Method -ParamsYaml $ParamsYaml
    if (-not $script:LastInvokeReplMethodSuccess) { exit 1 }
    exit 0
}

